int timer = 0;
void dfs(int v, int p){
    disc[v] = low[v] = ++timer;
    int kids = 0;
    bool art = false;
    for (int u : adj[v]) {
        if (u == p) continue;
        if (disc[u]) low[v] = min(low[v], disc[u]);        // back-edge
        else {
            dfs(u, v); kids++;
            low[v] = min(low[v], low[u]);
            if (low[u] > disc[v]) bridgeEdge({v,u});       // bridge
            if (p != -1 && low[u] >= disc[v]) art = true;   // articulation
        }
    }
    if (p == -1 && kids >= 2) art = true;                   // root rule
}

