timer = disc = low = [0]*n
def dfs(v, pe):                     # pe = parent EDGE id (not vertex!)
    global timer
    disc[v] = low[v] = timer; timer += 1
    for eid, u in adj_edges[v]:
        if eid == pe: continue      # skip the entry edge specifically
        if disc[u]:                 # back-edge
            low[v] = min(low[v], disc[u])
        else:
            dfs(u, eid)
            low[v] = min(low[v], low[u])
            if low[u] > disc[v]: bridge(eid)          # BRIDGE
            if low[u] >= disc[v]: articulation_candidate(v)

