deque<int> dq; vector<int> d(n, INF); d[s]=0; dq.push_front(s);
while(!dq.empty()){
    int v=dq.front(); dq.pop_front();
    for(auto [u,w]:adj[v]){
        if(d[v]+w < d[u]){
            d[u]=d[v]+w;
            w==0 ? dq.push_front(u) : dq.push_back(u);
        }
    }
}   // distances monotone through deque — O(V+E)
